// Keccak-256 implementation from scratch
// Based on the Keccak reference implementation (FIPS 202 variant / original Keccak)

// Note: Ethereum uses the original Keccak-256, NOT SHA3-256 (which differs in padding)
// The rate is 1088 bits (136 bytes), capacity is 512 bits

const KECCAK_ROUNDS: usize = 24;

// Round constants
const RC: [u64; 24] = [
    0x0000000000000001, 0x0000000000008082, 0x800000000000808A, 0x8000000080008000,
    0x000000000000808B, 0x0000000080000001, 0x8000000080008081, 0x8000000000008009,
    0x000000000000008A, 0x0000000000000088, 0x0000000080008009, 0x000000008000000A,
    0x000000008000808B, 0x800000000000008B, 0x8000000000008089, 0x8000000000008003,
    0x8000000000008002, 0x8000000000000080, 0x000000000000800A, 0x800000008000000A,
    0x8000000080008081, 0x8000000000008080, 0x0000000080000001, 0x8000000080008008,
];

// Rotation offsets
const RHO: [u32; 24] = [
    1, 3, 6, 10, 15, 21, 28, 36, 45, 55, 2, 14, 27, 41, 56, 8, 25, 43, 62, 18, 39, 61, 20, 44,
];

// Pi permutation indices
const PI: [usize; 24] = [
    10, 7, 11, 17, 18, 3, 5, 16, 8, 21, 24, 4, 15, 23, 19, 13, 12, 2, 20, 14, 22, 9, 6, 1,
];

fn keccakf(state: &mut [u64; 25]) {
    for round in 0..KECCAK_ROUNDS {
        // Theta step
        let mut c = [0u64; 5];
        for x in 0..5 {
            c[x] = state[x] ^ state[x + 5] ^ state[x + 10] ^ state[x + 15] ^ state[x + 20];
        }
        let mut d = [0u64; 5];
        for x in 0..5 {
            d[x] = c[(x + 4) % 5] ^ c[(x + 1) % 5].rotate_left(1);
        }
        for x in 0..5 {
            for y in 0..5 {
                state[x + y * 5] ^= d[x];
            }
        }

        // Rho and Pi steps
        let mut last = state[1];
        for i in 0..24 {
            let j = PI[i];
            let temp = state[j];
            state[j] = last.rotate_left(RHO[i]);
            last = temp;
        }

        // Chi step
        for y in 0..5 {
            let mut row = [0u64; 5];
            for x in 0..5 {
                row[x] = state[x + y * 5];
            }
            for x in 0..5 {
                state[x + y * 5] = row[x] ^ (!row[(x + 1) % 5] & row[(x + 2) % 5]);
            }
        }

        // Iota step
        state[0] ^= RC[round];
    }
}

pub fn keccak256(input: &[u8]) -> [u8; 32] {
    let rate = 136; // 1088 bits for keccak256
    let mut state = [0u64; 25];

    // Absorb phase
    let mut offset = 0;
    let mut buf = [0u8; 136];

    while offset + rate <= input.len() {
        for i in 0..rate {
            buf[i] = input[offset + i];
        }
        xor_into_state(&mut state, &buf, rate);
        keccakf(&mut state);
        offset += rate;
    }

    // Last block with padding
    let remaining = input.len() - offset;
    let mut last_block = [0u8; 136];
    last_block[..remaining].copy_from_slice(&input[offset..]);
    // Keccak padding: 0x01 (not 0x06 which is SHA3)
    last_block[remaining] = 0x01;
    last_block[rate - 1] ^= 0x80;

    xor_into_state(&mut state, &last_block, rate);
    keccakf(&mut state);

    // Squeeze phase - take first 32 bytes
    let mut output = [0u8; 32];
    let state_bytes = state_to_bytes(&state);
    output.copy_from_slice(&state_bytes[..32]);
    output
}

fn xor_into_state(state: &mut [u64; 25], block: &[u8], rate: usize) {
    for i in 0..(rate / 8) {
        let lane = u64::from_le_bytes([
            block[i*8], block[i*8+1], block[i*8+2], block[i*8+3],
            block[i*8+4], block[i*8+5], block[i*8+6], block[i*8+7],
        ]);
        state[i] ^= lane;
    }
}

fn state_to_bytes(state: &[u64; 25]) -> Vec<u8> {
    let mut bytes = Vec::with_capacity(200);
    for lane in state {
        bytes.extend_from_slice(&lane.to_le_bytes());
    }
    bytes
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_keccak256_empty() {
        let hash = keccak256(b"");
        let expected = hex::decode("c5d2460186f7233c927e7db2dcc703c0e500b653ca82273b7bfad8045d85a470").unwrap();
        assert_eq!(hash.to_vec(), expected);
    }

    #[test]
    fn test_transfer_sig() {
        let hash = keccak256(b"Transfer(address,address,uint256)");
        // First 4 bytes should be ddf252ad
        assert_eq!(hash[0], 0xdd);
        assert_eq!(hash[1], 0xf2);
        assert_eq!(hash[2], 0x52);
        assert_eq!(hash[3], 0xad);
    }
}
