// ABI type definitions

#[derive(Debug, Clone, PartialEq)]
pub enum Type {
    // Fixed-size types
    Uint(usize),   // uint8 to uint256 (step 8)
    Int(usize),    // int8 to int256 (step 8)
    Bool,
    Address,
    FixedBytes(usize),  // bytes1 to bytes32

    // Dynamic types
    Bytes,
    String,

    // Arrays
    FixedArray(Box<Type>, usize),  // T[k]
    Array(Box<Type>),              // T[]

    // Tuple
    Tuple(Vec<Type>),
}

impl Type {
    /// Returns true if this type is dynamic (requires offset in tuple encoding)
    pub fn is_dynamic(&self) -> bool {
        match self {
            Type::Bytes | Type::String | Type::Array(_) => true,
            Type::FixedArray(t, _) => t.is_dynamic(),
            Type::Tuple(types) => types.iter().any(|t| t.is_dynamic()),
            _ => false,
        }
    }

    /// Returns the canonical string representation (for signatures)
    pub fn to_signature_string(&self) -> String {
        match self {
            Type::Uint(n) => format!("uint{}", n),
            Type::Int(n) => format!("int{}", n),
            Type::Bool => "bool".to_string(),
            Type::Address => "address".to_string(),
            Type::FixedBytes(n) => format!("bytes{}", n),
            Type::Bytes => "bytes".to_string(),
            Type::String => "string".to_string(),
            Type::FixedArray(t, n) => format!("{}[{}]", t.to_signature_string(), n),
            Type::Array(t) => format!("{}[]", t.to_signature_string()),
            Type::Tuple(types) => {
                let inner = types.iter().map(|t| t.to_signature_string()).collect::<Vec<_>>().join(",");
                format!("({})", inner)
            }
        }
    }

    /// Display name for decode output
    pub fn display_name(&self) -> String {
        self.to_signature_string()
    }

    /// Parse a type string
    pub fn parse(s: &str) -> Result<Type, String> {
        parse_type(s.trim())
    }
}

fn parse_type(s: &str) -> Result<Type, String> {
    // Handle array types (check for trailing [] or [k])
    if let Some(t) = parse_array_suffix(s)? {
        return Ok(t);
    }

    // Handle tuple types
    if s.starts_with('(') {
        return parse_tuple(s);
    }

    // Handle base types
    match s {
        "bool" => return Ok(Type::Bool),
        "address" => return Ok(Type::Address),
        "bytes" => return Ok(Type::Bytes),
        "string" => return Ok(Type::String),
        _ => {}
    }

    // Handle uint/int/bytes with size
    if s.starts_with("uint") {
        let size_str = &s[4..];
        if size_str.is_empty() {
            return Ok(Type::Uint(256));
        }
        let size: usize = size_str.parse().map_err(|_| format!("Invalid uint size: {}", s))?;
        if size == 0 || size > 256 || size % 8 != 0 {
            return Err(format!("Invalid uint size: {}", size));
        }
        return Ok(Type::Uint(size));
    }

    if s.starts_with("int") {
        let size_str = &s[3..];
        if size_str.is_empty() {
            return Ok(Type::Int(256));
        }
        let size: usize = size_str.parse().map_err(|_| format!("Invalid int size: {}", s))?;
        if size == 0 || size > 256 || size % 8 != 0 {
            return Err(format!("Invalid int size: {}", size));
        }
        return Ok(Type::Int(size));
    }

    if s.starts_with("bytes") {
        let size_str = &s[5..];
        if size_str.is_empty() {
            return Ok(Type::Bytes);
        }
        let size: usize = size_str.parse().map_err(|_| format!("Invalid bytes size: {}", s))?;
        if size == 0 || size > 32 {
            return Err(format!("Invalid bytes size: {}", size));
        }
        return Ok(Type::FixedBytes(size));
    }

    Err(format!("Unknown type: {}", s))
}

/// Try to parse array suffix from a type string
/// Returns Ok(Some(type)) if array, Ok(None) if not, Err if malformed
fn parse_array_suffix(s: &str) -> Result<Option<Type>, String> {
    // Find the last [] or [k] that is at the top level
    // We need to handle tuples like (T1,T2)[] or (T1,T2)[3]

    if !s.ends_with(']') {
        return Ok(None);
    }

    // Find the matching '[' - it must not be inside a tuple or array
    let mut depth = 0i32;
    let bytes = s.as_bytes();
    let mut bracket_start = None;

    for i in (0..bytes.len()).rev() {
        match bytes[i] {
            b']' => depth += 1,
            b'[' => {
                depth -= 1;
                if depth == 0 {
                    bracket_start = Some(i);
                    break;
                }
            }
            b')' => depth += 1,
            b'(' => depth -= 1,
            _ => {}
        }
    }

    let bracket_start = match bracket_start {
        Some(i) => i,
        None => return Ok(None),
    };

    // Check that the [ is at the right depth (not inside a tuple)
    // Count parentheses before bracket_start
    let mut paren_depth = 0i32;
    for i in 0..bracket_start {
        match bytes[i] {
            b'(' => paren_depth += 1,
            b')' => paren_depth -= 1,
            _ => {}
        }
    }

    if paren_depth != 0 {
        return Ok(None);
    }

    let base_type_str = &s[..bracket_start];
    let size_str = &s[bracket_start+1..s.len()-1];

    let base_type = parse_type(base_type_str)?;

    if size_str.is_empty() {
        Ok(Some(Type::Array(Box::new(base_type))))
    } else {
        let size: usize = size_str.parse().map_err(|_| format!("Invalid array size: {}", size_str))?;
        Ok(Some(Type::FixedArray(Box::new(base_type), size)))
    }
}

fn parse_tuple(s: &str) -> Result<Type, String> {
    if !s.starts_with('(') {
        return Err(format!("Expected tuple starting with '(': {}", s));
    }

    // Find the matching ')'
    let mut depth = 0i32;
    let mut end = None;
    let bytes = s.as_bytes();

    for (i, &b) in bytes.iter().enumerate() {
        match b {
            b'(' => depth += 1,
            b')' => {
                depth -= 1;
                if depth == 0 {
                    end = Some(i);
                    break;
                }
            }
            _ => {}
        }
    }

    let end = end.ok_or_else(|| format!("Unclosed tuple: {}", s))?;

    // After the closing ), there might be array suffixes
    let tuple_content = &s[1..end];
    let after = &s[end+1..];

    // Parse the tuple element types
    let element_types = if tuple_content.is_empty() {
        vec![]
    } else {
        split_tuple_types(tuple_content)?
            .iter()
            .map(|t| parse_type(t))
            .collect::<Result<Vec<_>, _>>()?
    };

    let tuple_type = Type::Tuple(element_types);

    if after.is_empty() {
        Ok(tuple_type)
    } else {
        // Parse the rest as array suffix
        let full_with_suffix = format!("X{}", after);
        // Reconstruct the full type string with array suffix
        let full_type_str = format!("({}{}", tuple_content, after);
        // Parse it properly
        parse_tuple_with_suffix(&format!("({}){}", tuple_content, after[0..0].to_string()), after, tuple_type)
    }
}

fn parse_tuple_with_suffix(base: &str, suffix: &str, tuple_type: Type) -> Result<Type, String> {
    if suffix.is_empty() {
        return Ok(tuple_type);
    }

    // suffix should start with [ 
    if !suffix.starts_with('[') {
        return Err(format!("Unexpected characters after tuple: {}", suffix));
    }

    let close = suffix.find(']').ok_or_else(|| format!("Unclosed array bracket: {}", suffix))?;
    let size_str = &suffix[1..close];
    let rest = &suffix[close+1..];

    let arr_type = if size_str.is_empty() {
        Type::Array(Box::new(tuple_type))
    } else {
        let size: usize = size_str.parse().map_err(|_| format!("Invalid array size: {}", size_str))?;
        Type::FixedArray(Box::new(tuple_type), size)
    };

    if rest.is_empty() {
        Ok(arr_type)
    } else {
        parse_tuple_with_suffix(base, rest, arr_type)
    }
}

/// Split comma-separated type list, respecting parentheses depth
fn split_tuple_types(s: &str) -> Result<Vec<&str>, String> {
    let mut types = Vec::new();
    let mut depth = 0i32;
    let mut start = 0;
    let bytes = s.as_bytes();

    for (i, &b) in bytes.iter().enumerate() {
        match b {
            b'(' => depth += 1,
            b')' => depth -= 1,
            b',' if depth == 0 => {
                types.push(&s[start..i]);
                start = i + 1;
            }
            _ => {}
        }
    }
    types.push(&s[start..]);

    Ok(types)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_basic_types() {
        assert_eq!(Type::parse("bool"), Ok(Type::Bool));
        assert_eq!(Type::parse("uint256"), Ok(Type::Uint(256)));
        assert_eq!(Type::parse("int8"), Ok(Type::Int(8)));
        assert_eq!(Type::parse("address"), Ok(Type::Address));
        assert_eq!(Type::parse("bytes32"), Ok(Type::FixedBytes(32)));
        assert_eq!(Type::parse("bytes"), Ok(Type::Bytes));
        assert_eq!(Type::parse("string"), Ok(Type::String));
    }

    #[test]
    fn test_array_types() {
        assert_eq!(Type::parse("uint256[]"), Ok(Type::Array(Box::new(Type::Uint(256)))));
        assert_eq!(Type::parse("bool[3]"), Ok(Type::FixedArray(Box::new(Type::Bool), 3)));
    }

    #[test]
    fn test_tuple_types() {
        assert_eq!(Type::parse("(bool,uint256)"), Ok(Type::Tuple(vec![Type::Bool, Type::Uint(256)])));
    }

    #[test]
    fn test_signature_strings() {
        assert_eq!(Type::Uint(256).to_signature_string(), "uint256");
        assert_eq!(Type::Bool.to_signature_string(), "bool");
        assert_eq!(Type::Tuple(vec![Type::Bool, Type::Uint(256)]).to_signature_string(), "(bool,uint256)");
    }
}
