// ABI encoding implementation

use crate::types::Type;

/// A token value for encoding
#[derive(Debug, Clone)]
pub enum Token {
    Uint([u8; 32]),
    Int([u8; 32]),
    Bool(bool),
    Address([u8; 20]),
    FixedBytes(Vec<u8>),
    Bytes(Vec<u8>),
    String(std::string::String),
    FixedArray(Vec<Token>),
    Array(Vec<Token>),
    Tuple(Vec<Token>),
}

impl Token {
    pub fn is_dynamic(&self) -> bool {
        match self {
            Token::Bytes(_) | Token::String(_) | Token::Array(_) => true,
            Token::FixedArray(tokens) | Token::Tuple(tokens) => tokens.iter().any(|t| t.is_dynamic()),
            _ => false,
        }
    }
}

/// Encode a list of tokens into ABI-encoded bytes
pub fn encode(tokens: &[Token]) -> Vec<u8> {
    let mut head = Vec::new();
    let mut tail = Vec::new();

    // First pass: calculate total head size
    let head_size: usize = tokens.iter().map(|t| {
        if t.is_dynamic() { 32 } else { head_size_of(t) }
    }).sum();

    let mut offset = head_size;

    for token in tokens {
        if token.is_dynamic() {
            // Write offset to tail
            head.extend_from_slice(&pad_u256(offset as u64));
            let token_encoded = encode_token(token);
            offset += token_encoded.len();
            tail.extend(token_encoded);
        } else {
            // Write inline
            head.extend(encode_token(token));
        }
    }

    head.extend(tail);
    head
}

fn head_size_of(token: &Token) -> usize {
    match token {
        Token::FixedArray(tokens) => {
            tokens.iter().map(|t| {
                if t.is_dynamic() { 32 } else { head_size_of(t) }
            }).sum()
        }
        Token::Tuple(tokens) => {
            tokens.iter().map(|t| {
                if t.is_dynamic() { 32 } else { head_size_of(t) }
            }).sum()
        }
        _ => 32,
    }
}

fn encode_token(token: &Token) -> Vec<u8> {
    match token {
        Token::Uint(v) => v.to_vec(),
        Token::Int(v) => v.to_vec(),
        Token::Bool(b) => {
            let mut bytes = [0u8; 32];
            if *b { bytes[31] = 1; }
            bytes.to_vec()
        }
        Token::Address(addr) => {
            let mut bytes = [0u8; 32];
            bytes[12..32].copy_from_slice(addr);
            bytes.to_vec()
        }
        Token::FixedBytes(v) => {
            let mut bytes = [0u8; 32];
            let len = v.len().min(32);
            bytes[..len].copy_from_slice(&v[..len]);
            bytes.to_vec()
        }
        Token::Bytes(v) => {
