pub fn hex_decode(s: &str) -> Result<Vec<u8>, String> {
    if s.len() % 2 != 0 {
        return Err("Odd number of digits".to_string());
    }
    let mut bytes = Vec::with_capacity(s.len() / 2);
    for i in (0..s.len()).step_by(2) {
        let hi = hex_nibble(s.as_bytes()[i]).map_err(|e| format!("Invalid character '{}' at position {}", s.as_bytes()[i] as char, i))?;
        let lo = hex_nibble(s.as_bytes()[i+1]).map_err(|e| format!("Invalid character '{}' at position {}", s.as_bytes()[i+1] as char, i+1))?;
        bytes.push((hi << 4) | lo);
    }
    Ok(bytes)
}

