        }
        if carry != 0 {
            return Err("overflow".to_string());
        }

        // Add digit
        let mut carry2: u16 = digit as u16;
        for i in (0..32).rev() {
            let v = result[i] as u16 + carry2;
            result[i] = (v & 0xFF) as u8;
            carry2 = v >> 8;
