    }
    let tokens: Result<Vec<_>, _> = parts.iter().zip(types.iter())
        .map(|(p, t)| parse_param_inner(t, p.trim(), lenient))
        .collect();
    Ok(Token::Tuple(tokens?))
}

/// Split array elements respecting nested brackets
fn split_array_elements(s: &str) -> Result<Vec<&str>, String> {
    let mut elements = Vec::new();
    let mut depth = 0i32;
    let mut start = 0;
    let bytes = s.as_bytes();

    for (i, &b) in bytes.iter().enumerate() {
        match b {
            b'[' | b'(' => depth += 1,
            b']' | b')' => depth -= 1,
            b',' if depth == 0 => {
                elements.push(&s[start..i]);
                start = i + 1;
            }
            _ => {}
        }
    }
    if start <= s.len() {
        elements.push(&s[start..]);
    }

    Ok(elements)
}

fn split_tuple_elements(s: &str) -> Result<Vec<&str>, String> {
    split_array_elements(s)
}

// Hex parsing
pub fn hex_decode(s: &str) -> Result<Vec<u8>, String> {
    if s.len() % 2 != 0 {
        return Err("Odd number of digits".to_string());
    }
    let mut bytes = Vec::with_capacity(s.len() / 2);
    for i in (0..s.len()).step_by(2) {
        let hi = hex_nibble(s.as_bytes()[i]).map_err(|e| format!("Invalid character '{}' at position {}", s.as_bytes()[i] as char, i))?;
        let lo = hex_nibble(s.as_bytes()[i+1]).map_err(|e| format!("Invalid character '{}' at position {}", s.as_bytes()[i+1] as char, i+1))?;
        bytes.push((hi << 4) | lo);
    }
    Ok(bytes)
}

fn hex_nibble(b: u8) -> Result<u8, String> {
    match b {
        b'0'..=b'9' => Ok(b - b'0'),
        b'a'..=b'f' => Ok(b - b'a' + 10),
        b'A'..=b'F' => Ok(b - b'A' + 10),
        _ => Err(format!("invalid hex byte: {}", b as char)),
    }
}

fn parse_hex_u256(s: &str) -> Result<[u8; 32], String> {
    if s.len() != 64 {
        return Err("Invalid data".to_string());
    }
    let bytes = hex_decode(s).map_err(|e| e)?;
    let mut arr = [0u8; 32];
    arr.copy_from_slice(&bytes);
    Ok(arr)
}

fn decimal_to_u256_bytes(s: &str) -> Result<[u8; 32], String> {
    let mut result = [0u8; 32];

    if s.is_empty() {
        return Err("empty".to_string());
    }

    for ch in s.chars() {
        if !ch.is_ascii_digit() {
            return Err(format!("invalid char: {}", ch));
        }
        let digit = ch as u8 - b'0';

        // Multiply result by 10
        let mut carry: u16 = 0;
        for i in (0..32).rev() {
            let v = result[i] as u16 * 10 + carry;
            result[i] = (v & 0xFF) as u8;
            carry = v >> 8;
        }
        if carry != 0 {
            return Err("overflow".to_string());
        }

        // Add digit
        let mut carry2: u16 = digit as u16;
        for i in (0..32).rev() {
            let v = result[i] as u16 + carry2;
            result[i] = (v & 0xFF) as u8;
            carry2 = v >> 8;
            if carry2 == 0 { break; }
        }
        if carry2 != 0 {
            return Err("overflow".to_string());
        }
    }

    Ok(result)
}

fn negative_decimal_to_i256_bytes(s: &str) -> Result<[u8; 32], String> {
    // Parse the positive value then negate (two's complement)
    let positive = decimal_to_u256_bytes(s)?;

    // Two's complement negation
    let mut result = [0u8; 32];
    for i in 0..32 {
        result[i] = !positive[i];
    }

    // Add 1
    let mut carry: u16 = 1;
    for i in (0..32).rev() {
        let v = result[i] as u16 + carry;
        result[i] = (v & 0xFF) as u8;
        carry = v >> 8;
        if carry == 0 { break; }
    }

    Ok(result)
}
