// ABI decoding implementation

use crate::types::Type;
use crate::encode::Token;

#[derive(Debug)]
pub enum DecodeError {
    InvalidData,
    EmptyData,
    InvalidCharacter(String),
    OddNumberOfDigits,
}

impl std::fmt::Display for DecodeError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            DecodeError::InvalidData => write!(f, "Invalid data"),
            DecodeError::EmptyData => write!(f, "Invalid name: please ensure the contract and method you're calling exist! failed to decode empty bytes. if you're using jsonrpc this is likely due to jsonrpc returning `0x` in case contract or method don't exist"),
            DecodeError::InvalidCharacter(s) => write!(f, "{}", s),
            DecodeError::OddNumberOfDigits => write!(f, "Odd number of digits"),
        }
    }
}

/// Decode hex string to bytes
pub fn decode_hex(s: &str) -> Result<Vec<u8>, DecodeError> {
    if s.is_empty() {
        return Ok(vec![]);
    }
    if s.len() % 2 != 0 {
        return Err(DecodeError::OddNumberOfDigits);
    }
    let mut bytes = Vec::with_capacity(s.len() / 2);
    for i in (0..s.len()).step_by(2) {
        let hi = hex_nibble(s.as_bytes()[i])
            .map_err(|_| DecodeError::InvalidCharacter(format!("Invalid character '{}' at position {}", s.as_bytes()[i] as char, i)))?;
        let lo = hex_nibble(s.as_bytes()[i+1])
            .map_err(|_| DecodeError::InvalidCharacter(format!("Invalid character '{}' at position {}", s.as_bytes()[i+1] as char, i+1)))?;
        bytes.push((hi << 4) | lo);
    }
    Ok(bytes)
}

fn hex_nibble(b: u8) -> Result<u8, ()> {
    match b {
        b'0'..=b'9' => Ok(b - b'0'),
        b'a'..=b'f' => Ok(b - b'a' + 10),
        b'A'..=b'F' => Ok(b - b'A' + 10),
        _ => Err(()),
    }
}

/// Decode a list of types from ABI-encoded data
pub fn decode(types: &[Type], data: &[u8]) -> Result<Vec<Token>, DecodeError> {
    if data.is_empty() && !types.is_empty() {
        return Err(DecodeError::EmptyData);
    }

    decode_params(types, data, 0)
}

fn decode_params(types: &[Type], data: &[u8], base_offset: usize) -> Result<Vec<Token>, DecodeError> {
    let mut tokens = Vec::new();
    let mut pos = 0;

    for type_ in types {
        if type_.is_dynamic() {
            // Read offset
            if pos + 32 > data.len() {
                return Err(DecodeError::InvalidData);
            }
            let offset = read_u256_as_usize(&data[pos..pos+32])?;
            pos += 32;

            let token = decode_single(type_, data, offset)?;
            tokens.push(token);
        } else {
            if pos + 32 > data.len() && !is_static_zero_size(type_) {
                return Err(DecodeError::InvalidData);
            }
            // Check we have enough data
            let size = static_size(type_);
            if pos + size > data.len() {
                return Err(DecodeError::InvalidData);
            }
            let token = decode_static(type_, &data[pos..pos+size])?;
            tokens.push(token);
            pos += size;
        }
    }

    Ok(tokens)
}

fn is_static_zero_size(type_: &Type) -> bool {
    false
}

fn static_size(type_: &Type) -> usize {
    match type_ {
        Type::FixedArray(inner, n) => static_size(inner) * n,
        Type::Tuple(types) => types.iter().map(|t| {
            if t.is_dynamic() { 32 } else { static_size(t) }
        }).sum(),
        _ => 32,
    }
}

fn decode_static(type_: &Type, data: &[u8]) -> Result<Token, DecodeError> {
    match type_ {
        Type::Bool => {
            if data.len() < 32 { return Err(DecodeError::InvalidData); }
            let val = data[31];
            if val > 1 { return Err(DecodeError::InvalidData); }
            // Check all other bytes are 0
            for i in 0..31 {
                if data[i] != 0 { return Err(DecodeError::InvalidData); }
            }
            Ok(Token::Bool(val == 1))
        }
        Type::Uint(_) => {
            if data.len() < 32 { return Err(DecodeError::InvalidData); }
            let mut arr = [0u8; 32];
            arr.copy_from_slice(&data[..32]);
            Ok(Token::Uint(arr))
        }
        Type::Int(_) => {
            if data.len() < 32 { return Err(DecodeError::InvalidData); }
            let mut arr = [0u8; 32];
            arr.copy_from_slice(&data[..32]);
            Ok(Token::Int(arr))
        }
        Type::Address => {
            if data.len() < 32 { return Err(DecodeError::InvalidData); }
            // Validate first 12 bytes are 0
            for i in 0..12 {
                if data[i] != 0 { return Err(DecodeError::InvalidData); }
            }
            let mut addr = [0u8; 20];
            addr.copy_from_slice(&data[12..32]);
            Ok(Token::Address(addr))
        }
        Type::FixedBytes(n) => {
            if data.len() < 32 { return Err(DecodeError::InvalidData); }
            let bytes = data[..*n].to_vec();
            Ok(Token::FixedBytes(bytes))
        }
        Type::FixedArray(inner, n) => {
            let mut tokens = Vec::new();
            let mut pos = 0;

            if inner.is_dynamic() {
                // Each element is an offset
                for _ in 0..*n {
                    if pos + 32 > data.len() { return Err(DecodeError::InvalidData); }
                    let offset = read_u256_as_usize(&data[pos..pos+32])?;
                    pos += 32;
                    let token = decode_single(inner, data, offset)?;
                    tokens.push(token);
                }
            } else {
                let elem_size = static_size(inner);
                for _ in 0..*n {
                    if pos + elem_size > data.len() { return Err(DecodeError::InvalidData); }
                    let token = decode_static(inner, &data[pos..pos+elem_size])?;
                    tokens.push(token);
                    pos += elem_size;
                }
            }

            Ok(Token::FixedArray(tokens))
        }
        Type::Tuple(types) => {
            let tokens = decode_params(types, data, 0)?;
            Ok(Token::Tuple(tokens))
        }
        _ => Err(DecodeError::InvalidData),
    }
}

fn decode_single(type_: &Type, data: &[u8], offset: usize) -> Result<Token, DecodeError> {
    match type_ {
        Type::Bytes => {
            if offset + 32 > data.len() { return Err(DecodeError::InvalidData); }
            let len = read_u256_as_usize(&data[offset..offset+32])?;
            if offset + 32 + len > data.len() { return Err(DecodeError::InvalidData); }
            Ok(Token::Bytes(data[offset+32..offset+32+len].to_vec()))
        }
        Type::String => {
            if offset + 32 > data.len() { return Err(DecodeError::InvalidData); }
            let len = read_u256_as_usize(&data[offset..offset+32])?;
            if offset + 32 + len > data.len() { return Err(DecodeError::InvalidData); }
            let s = std::str::from_utf8(&data[offset+32..offset+32+len])
                .map_err(|_| DecodeError::InvalidData)?;
            Ok(Token::String(s.to_string()))
        }
        Type::Array(inner) => {
            if offset + 32 > data.len() { return Err(DecodeError::InvalidData); }
            let len = read_u256_as_usize(&data[offset..offset+32])?;
            let array_data = &data[offset+32..];

            let mut tokens = Vec::new();
            let mut pos = 0;

            if inner.is_dynamic() {
                for _ in 0..len {
                    if pos + 32 > array_data.len() { return Err(DecodeError::InvalidData); }
                    let elem_offset = read_u256_as_usize(&array_data[pos..pos+32])?;
                    pos += 32;
                    let token = decode_single(inner, array_data, elem_offset)?;
                    tokens.push(token);
                }
            } else {
                let elem_size = static_size(inner);
                for _ in 0..len {
                    if pos + elem_size > array_data.len() { return Err(DecodeError::InvalidData); }
                    let token = decode_static(inner, &array_data[pos..pos+elem_size])?;
                    tokens.push(token);
                    pos += elem_size;
                }
            }

            Ok(Token::Array(tokens))
        }
        Type::FixedArray(inner, n) => {
            let array_data = &data[offset..];

            let mut tokens = Vec::new();
            let mut pos = 0;

            if inner.is_dynamic() {
                for _ in 0..*n {
                    if pos + 32 > array_data.len() { return Err(DecodeError::InvalidData); }
                    let elem_offset = read_u256_as_usize(&array_data[pos..pos+32])?;
                    pos += 32;
                    let token = decode_single(inner, array_data, elem_offset)?;
                    tokens.push(token);
                }
            } else {
                let elem_size = static_size(inner);
                for _ in 0..*n {
                    if pos + elem_size > array_data.len() { return Err(DecodeError::InvalidData); }
                    let token = decode_static(inner, &array_data[pos..pos+elem_size])?;
                    tokens.push(token);
                    pos += elem_size;
                }
            }

            Ok(Token::FixedArray(tokens))
        }
        Type::Tuple(types) => {
            let tuple_data = &data[offset..];
            let tokens = decode_params(types, tuple_data, 0)?;
            Ok(Token::Tuple(tokens))
        }
        _ => {
            // Static type accessed via offset (shouldn't normally happen)
            if offset + 32 > data.len() { return Err(DecodeError::InvalidData); }
            decode_static(type_, &data[offset..offset+32])
        }
    }
}

fn read_u256_as_usize(data: &[u8]) -> Result<usize, DecodeError> {
    if data.len() < 32 { return Err(DecodeError::InvalidData); }
    // Check that the upper bytes are 0
    for i in 0..24 {
        if data[i] != 0 { return Err(DecodeError::InvalidData); }
    }
    let val = u64::from_be_bytes([data[24], data[25], data[26], data[27], data[28], data[29], data[30], data[31]]);
    Ok(val as usize)
}

/// Format a token for output (decode output)
pub fn format_token(token: &Token) -> String {
    match token {
        Token::Bool(b) => if *b { "true".to_string() } else { "false".to_string() },
        Token::Uint(v) | Token::Int(v) => {
            // Hex without leading zeros (but always at least one digit)
            let hex = hex_encode(v);
            // Strip leading zeros
            let stripped = hex.trim_start_matches('0');
            if stripped.is_empty() { "0".to_string() } else { stripped.to_string() }
        }
        Token::Address(addr) => hex_encode(addr),
        Token::FixedBytes(v) => hex_encode(v),
        Token::Bytes(v) => hex_encode(v),
        Token::String(s) => s.clone(),
        Token::FixedArray(tokens) | Token::Array(tokens) => {
            let inner: Vec<String> = tokens.iter().map(format_token).collect();
            format!("[{}]", inner.join(","))
        }
        Token::Tuple(tokens) => {
            let inner: Vec<String> = tokens.iter().map(format_token).collect();
            format!("({})", inner.join(","))
        }
    }
}

pub fn hex_encode(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{:02x}", b)).collect()
}
