    pub inputs: Vec<AbiParam>,
    pub outputs: Vec<AbiParam>,
}

#[derive(Debug, Clone)]
pub struct AbiEvent {
    pub name: String,
    pub anonymous: bool,
    pub inputs: Vec<AbiEventParam>,
}

#[derive(Debug, Clone)]
pub struct AbiEventParam {
    pub name: String,
    pub type_: Type,
    pub indexed: bool,
    pub components: Vec<AbiParam>,
}

#[derive(Debug)]
pub struct Contract {
    pub functions: Vec<AbiFunction>,
    pub events: Vec<AbiEvent>,
}

impl Contract {
    /// Parse a JSON ABI file
    pub fn from_json(json: &str) -> Result<Contract, String> {
        parse_abi_json(json)
    }

    /// Find a function by name or short signature
    pub fn find_function(&self, name_or_sig: &str) -> Result<&AbiFunction, String> {
        if name_or_sig.contains('(') {
            // It's a signature: name(types...)
            // Parse as a short signature and find matching function
            find_function_by_signature(&self.functions, name_or_sig)
        } else {
            // It's just a name
            let matches: Vec<_> = self.functions.iter()
                .filter(|f| f.name == name_or_sig)
                .collect();

            match matches.len() {
                0 => Err(format!("Invalid name: {}", name_or_sig)),
                1 => Ok(matches[0]),
                _ => Err(format!("More than one function found for name `{}`, try providing the full signature", name_or_sig)),
            }
        }
    }

    /// Find an event by name or signature
    pub fn find_event(&self, name_or_sig: &str) -> Result<&AbiEvent, String> {
        if name_or_sig.contains('(') {
            find_event_by_signature(&self.events, name_or_sig)
        } else {
            let matches: Vec<_> = self.events.iter()
                .filter(|e| e.name == name_or_sig)
                .collect();

            match matches.len() {
                0 => Err(format!("Invalid name: {}", name_or_sig)),
                1 => Ok(matches[0]),
                _ => Err(format!("More than one event found for name `{}`, try providing the full signature", name_or_sig)),
            }
        }
    }
}

fn find_function_by_signature<'a>(functions: &'a [AbiFunction], sig: &str) -> Result<&'a AbiFunction, String> {
    // Parse the signature: name(type1,type2,...)
    let paren_pos = sig.find('(')
        .ok_or_else(|| format!("invalid function signature `{}`", sig))?;

    let name = &sig[..paren_pos];
    let types_str = &sig[paren_pos+1..sig.len()-1]; // remove the parentheses

    // Parse the types
    let input_types = if types_str.is_empty() {
        vec![]
    } else {
        parse_sig_types(types_str)
            .map_err(|_| format!("invalid function signature `{}`", sig))?
    };

    // Find matching function
    // Only match functions with empty outputs (this is the observed behavior)
    for func in functions {
        if func.name != name {
            continue;
        }

        if !func.outputs.is_empty() {
            continue;
        }

        // Check input types match
        if func.inputs.len() != input_types.len() {
            continue;
        }

        let types_match = func.inputs.iter().zip(input_types.iter())
            .all(|(param, type_)| {
                &param.type_ == type_
            });

        if types_match {
            return Ok(func);
        }
    }

    Err(format!("invalid function signature `{}`", sig))
}

fn find_event_by_signature<'a>(events: &'a [AbiEvent], sig: &str) -> Result<&'a AbiEvent, String> {
    let paren_pos = sig.find('(')
        .ok_or_else(|| format!("invalid event signature `{}`", sig))?;

    let name = &sig[..paren_pos];
    let types_str = &sig[paren_pos+1..sig.len()-1];

    let input_types = if types_str.is_empty() {
        vec![]
    } else {
        parse_sig_types(types_str)
            .map_err(|_| format!("invalid event signature `{}`", sig))?
    };

    for event in events {
        if event.name != name {
            continue;
        }

        let non_indexed: Vec<_> = event.inputs.iter().collect();

        // Check all input types (indexed and non-indexed)
        if event.inputs.len() != input_types.len() {
            continue;
        }

        let types_match = event.inputs.iter().zip(input_types.iter())
            .all(|(param, type_)| {
                &param.type_ == type_
            });

        if types_match {
            return Ok(event);
        }
    }

    Err(format!("invalid event signature `{}`", sig))
}

fn parse_sig_types(s: &str) -> Result<Vec<Type>, String> {
    if s.is_empty() {
        return Ok(vec![]);
    }

    // Split by commas at depth 0
    let parts = split_by_comma(s);
    parts.iter().map(|p| Type::parse(p)).collect()
}

fn split_by_comma(s: &str) -> Vec<&str> {
    let mut parts = Vec::new();
    let mut depth = 0i32;
    let mut start = 0;

    for (i, b) in s.bytes().enumerate() {
        match b {
            b'(' | b'[' => depth += 1,
            b')' | b']' => depth -= 1,
            b',' if depth == 0 => {
                parts.push(&s[start..i]);
                start = i + 1;
            }
            _ => {}
        }
    }
    parts.push(&s[start..]);
    parts
}

pub fn function_signature(func: &AbiFunction) -> String {
    let types: Vec<String> = func.inputs.iter()
        .map(|p| p.type_.to_signature_string())
        .collect();
    format!("{}({})", func.name, types.join(","))
}

pub fn event_signature(event: &AbiEvent) -> String {
    let types: Vec<String> = event.inputs.iter()
        .map(|p| p.type_.to_signature_string())
        .collect();
    format!("{}({})", event.name, types.join(","))
}

pub fn function_selector(func: &AbiFunction) -> [u8; 4] {
    let sig = function_signature(func);
    let hash = keccak256(sig.as_bytes());
    [hash[0], hash[1], hash[2], hash[3]]
}

pub fn event_selector(event: &AbiEvent) -> [u8; 32] {
    let sig = event_signature(event);
    keccak256(sig.as_bytes())
}

// Simple JSON parser for ABI
fn parse_abi_json(json: &str) -> Result<Contract, String> {
    let items = json_parse_array(json.trim())?;

    let mut functions = Vec::new();
    let mut events = Vec::new();

    for item in items {
        let type_ = json_get_string(&item, "type").unwrap_or_default();

        match type_.as_str() {
            "function" => {
                let func = parse_function_item(&item)?;
                functions.push(func);
            }
            "event" => {
                let event = parse_event_item(&item)?;
                events.push(event);
            }
            "constructor" | "fallback" | "receive" | "error" | "" => {
                // Skip these
            }
            _ => {
                // Unknown type, skip
            }
        }
    }

    Ok(Contract { functions, events })
}

fn parse_function_item(item: &JsonValue) -> Result<AbiFunction, String> {
    let name = json_get_string(item, "name").unwrap_or_default();
    let inputs = parse_params(json_get_array(item, "inputs").unwrap_or_default())?;
    let outputs = parse_params(json_get_array(item, "outputs").unwrap_or_default())?;

    Ok(AbiFunction { name, inputs, outputs })
}

fn parse_event_item(item: &JsonValue) -> Result<AbiEvent, String> {
    let name = json_get_string(item, "name").unwrap_or_default();
    let anonymous = json_get_bool(item, "anonymous").unwrap_or(false);
    let inputs_json = json_get_array(item, "inputs").unwrap_or_default();

    let mut inputs = Vec::new();
    for input in inputs_json {
        let param_name = json_get_string(&input, "name").unwrap_or_default();
        let type_str = json_get_string(&input, "type").unwrap_or_default();
        let indexed = json_get_bool(&input, "indexed").unwrap_or(false);
        let components = parse_components(json_get_array(&input, "components").unwrap_or_default())?;

        let type_ = if type_str == "tuple" {
            let comp_types: Vec<Type> = components.iter().map(|c| c.type_.clone()).collect();
            Type::Tuple(comp_types)
        } else if type_str.starts_with("tuple") {
            let suffix = &type_str[5..];
            let comp_types: Vec<Type> = components.iter().map(|c| c.type_.clone()).collect();
            apply_array_suffix(Type::Tuple(comp_types), suffix)?
        } else {
            Type::parse(&type_str)?
        };

        inputs.push(AbiEventParam { name: param_name, type_, indexed, components });
    }

    Ok(AbiEvent { name, anonymous, inputs })
}

fn parse_params(params: Vec<JsonValue>) -> Result<Vec<AbiParam>, String> {
    params.iter().map(|p| parse_param_item(p)).collect()
}

fn parse_param_item(item: &JsonValue) -> Result<AbiParam, String> {
    let name = json_get_string(item, "name").unwrap_or_default();
    let type_str = json_get_string(item, "type").unwrap_or_default();
    let components = parse_components(json_get_array(item, "components").unwrap_or_default())?;

    let type_ = if type_str == "tuple" {
        let comp_types: Vec<Type> = components.iter().map(|c| c.type_.clone()).collect();
        Type::Tuple(comp_types)
    } else if type_str.starts_with("tuple") {
        let suffix = &type_str[5..];
        let comp_types: Vec<Type> = components.iter().map(|c| c.type_.clone()).collect();
        apply_array_suffix(Type::Tuple(comp_types), suffix)?
    } else {
        Type::parse(&type_str)?
    };

    Ok(AbiParam { name, type_, components })
}

fn parse_components(components: Vec<JsonValue>) -> Result<Vec<AbiParam>, String> {
    components.iter().map(|c| parse_param_item(c)).collect()
}

fn apply_array_suffix(t: Type, suffix: &str) -> Result<Type, String> {
    if suffix.is_empty() {
        return Ok(t);
    }

    if !suffix.starts_with('[') {
        return Err(format!("Invalid type suffix: {}", suffix));
    }

    let close = suffix.find(']')
        .ok_or_else(|| format!("Unclosed bracket in type suffix: {}", suffix))?;
    let size_str = &suffix[1..close];
    let rest = &suffix[close+1..];

    let arr_type = if size_str.is_empty() {
        crate::types::Type::Array(Box::new(t))
    } else {
        let size: usize = size_str.parse()
            .map_err(|_| format!("Invalid array size: {}", size_str))?;
        crate::types::Type::FixedArray(Box::new(t), size)
    };

    apply_array_suffix(arr_type, rest)
}

// Simple JSON value type
#[derive(Debug, Clone)]
pub enum JsonValue {
    Null,
    Bool(bool),
    Number(f64),
    String(std::string::String),
    Array(Vec<JsonValue>),
    Object(Vec<(std::string::String, JsonValue)>),
}

fn json_get_string(val: &JsonValue, key: &str) -> Option<String> {
    if let JsonValue::Object(fields) = val {
        for (k, v) in fields {
            if k == key {
                if let JsonValue::String(s) = v {
                    return Some(s.clone());
                }
            }
        }
    }
    None
}

fn json_get_bool(val: &JsonValue, key: &str) -> Option<bool> {
    if let JsonValue::Object(fields) = val {
        for (k, v) in fields {
            if k == key {
                if let JsonValue::Bool(b) = v {
                    return Some(*b);
                }
            }
        }
    }
    None
}

fn json_get_array(val: &JsonValue, key: &str) -> Option<Vec<JsonValue>> {
    if let JsonValue::Object(fields) = val {
        for (k, v) in fields {
            if k == key {
                if let JsonValue::Array(arr) = v {
                    return Some(arr.clone());
                }
            }
        }
    }
    None
}

fn json_parse_array(s: &str) -> Result<Vec<JsonValue>, String> {
    let s = s.trim();
    if s.starts_with('[') {
        if let (JsonValue::Array(arr), _) = parse_json_value(s, 0)? {
            return Ok(arr);
        }
    }
    Err(format!("Expected JSON array"))
}

fn parse_json_value(s: &str, pos: usize) -> Result<(JsonValue, usize), String> {
    let bytes = s.as_bytes();
    let mut i = pos;

    // Skip whitespace
    while i < bytes.len() && (bytes[i] == b' ' || bytes[i] == b'\t' || bytes[i] == b'\n' || bytes[i] == b'\r') {
        i += 1;
    }

    if i >= bytes.len() {
        return Err("Unexpected end of JSON".to_string());
    }

    match bytes[i] {
        b'{' => parse_json_object(s, i),
        b'[' => parse_json_array_value(s, i),
        b'"' => parse_json_string(s, i),
        b't' => {
            if s[i..].starts_with("true") {
                Ok((JsonValue::Bool(true), i + 4))
            } else {
                Err(format!("Invalid JSON at position {}", i))
            }
        }
        b'f' => {
            if s[i..].starts_with("false") {
                Ok((JsonValue::Bool(false), i + 5))
            } else {
                Err(format!("Invalid JSON at position {}", i))
            }
        }
        b'n' => {
            if s[i..].starts_with("null") {
                Ok((JsonValue::Null, i + 4))
            } else {
                Err(format!("Invalid JSON at position {}", i))
            }
        }
        b'0'..=b'9' | b'-' => parse_json_number(s, i),
        _ => Err(format!("Unexpected character '{}' at position {}", bytes[i] as char, i)),
    }
}

fn skip_whitespace(bytes: &[u8], mut i: usize) -> usize {
    while i < bytes.len() && (bytes[i] == b' ' || bytes[i] == b'\t' || bytes[i] == b'\n' || bytes[i] == b'\r') {
        i += 1;
    }
    i
}

fn parse_json_object(s: &str, pos: usize) -> Result<(JsonValue, usize), String> {
    let bytes = s.as_bytes();
    let mut i = pos + 1; // skip '{'
    let mut fields = Vec::new();

    i = skip_whitespace(bytes, i);

    if i < bytes.len() && bytes[i] == b'}' {
        return Ok((JsonValue::Object(fields), i + 1));
    }

    loop {
        i = skip_whitespace(bytes, i);

        // Parse key
        let (key_val, new_i) = parse_json_string(s, i)?;
        let key = if let JsonValue::String(k) = key_val { k } else { return Err("Expected string key".to_string()); };
        i = new_i;

        i = skip_whitespace(bytes, i);

        if i >= bytes.len() || bytes[i] != b':' {
            return Err(format!("Expected ':' at position {}", i));
        }
        i += 1;

        i = skip_whitespace(bytes, i);

        // Parse value
        let (val, new_i) = parse_json_value(s, i)?;
        fields.push((key, val));
        i = new_i;

        i = skip_whitespace(bytes, i);

        if i >= bytes.len() {
            return Err("Unexpected end of JSON object".to_string());
        }

        match bytes[i] {
            b',' => { i += 1; }
            b'}' => { i += 1; break; }
            _ => return Err(format!("Expected ',' or '}}' at position {}", i)),
        }
    }

    Ok((JsonValue::Object(fields), i))
}

fn parse_json_array_value(s: &str, pos: usize) -> Result<(JsonValue, usize), String> {
    let bytes = s.as_bytes();
    let mut i = pos + 1; // skip '['
    let mut items = Vec::new();

    i = skip_whitespace(bytes, i);

    if i < bytes.len() && bytes[i] == b']' {
        return Ok((JsonValue::Array(items), i + 1));
    }

    loop {
        i = skip_whitespace(bytes, i);

        let (val, new_i) = parse_json_value(s, i)?;
        items.push(val);
        i = new_i;

        i = skip_whitespace(bytes, i);

        if i >= bytes.len() {
            return Err("Unexpected end of JSON array".to_string());
        }

        match bytes[i] {
            b',' => { i += 1; }
            b']' => { i += 1; break; }
            _ => return Err(format!("Expected ',' or ']' at position {}", i)),
        }
    }

    Ok((JsonValue::Array(items), i))
}

fn parse_json_string(s: &str, pos: usize) -> Result<(JsonValue, usize), String> {
    let bytes = s.as_bytes();
    if bytes[pos] != b'"' {
        return Err(format!("Expected '\"' at position {}", pos));
    }

    let mut result = String::new();
    let mut i = pos + 1;

    while i < bytes.len() {
        match bytes[i] {
            b'"' => {
                i += 1;
                return Ok((JsonValue::String(result), i));
            }
            b'\\' => {
                i += 1;
                if i >= bytes.len() {
                    return Err("Unexpected end of string escape".to_string());
                }
                match bytes[i] {
                    b'"' => result.push('"'),
                    b'\\' => result.push('\\'),
                    b'/' => result.push('/'),
                    b'n' => result.push('\n'),
                    b'r' => result.push('\r'),
                    b't' => result.push('\t'),
                    b'b' => result.push('\x08'),
                    b'f' => result.push('\x0C'),
                    b'u' => {
                        // Unicode escape \uXXXX
                        if i + 4 >= bytes.len() {
                            return Err("Invalid unicode escape".to_string());
                        }
                        let hex_str = &s[i+1..i+5];
                        let code_point = u32::from_str_radix(hex_str, 16)
                            .map_err(|_| format!("Invalid unicode escape at position {}", i))?;
                        if let Some(ch) = char::from_u32(code_point) {
                            result.push(ch);
                        }
                        i += 4;
                    }
                    c => {
                        result.push('\\');
                        result.push(c as char);
                    }
                }
                i += 1;
            }
            b => {
                result.push(b as char);
                i += 1;
            }
        }
    }

    Err("Unterminated string".to_string())
}

fn parse_json_number(s: &str, pos: usize) -> Result<(JsonValue, usize), String> {
    let bytes = s.as_bytes();
    let mut i = pos;

    if i < bytes.len() && bytes[i] == b'-' {
        i += 1;
    }

    while i < bytes.len() && bytes[i].is_ascii_digit() {
        i += 1;
    }

    if i < bytes.len() && bytes[i] == b'.' {
        i += 1;
        while i < bytes.len() && bytes[i].is_ascii_digit() {
            i += 1;
        }
    }

    if i < bytes.len() && (bytes[i] == b'e' || bytes[i] == b'E') {
        i += 1;
        if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
            i += 1;
        }
        while i < bytes.len() && bytes[i].is_ascii_digit() {
            i += 1;
        }
    }

    let num_str = &s[pos..i];
    let num: f64 = num_str.parse().map_err(|_| format!("Invalid number: {}", num_str))?;

    Ok((JsonValue::Number(num), i))
}
