fn find_function_by_signature<'a>(functions: &'a [AbiFunction], sig: &str) -> Result<&'a AbiFunction, String> {
    // Parse the signature: name(type1,type2,...)
    let paren_pos = sig.find('(')
        .ok_or_else(|| format!("invalid function signature `{}`", sig))?;

    let name = &sig[..paren_pos];
    let types_str = &sig[paren_pos+1..sig.len()-1]; // remove the parentheses

    // Parse the types
    let input_types = if types_str.is_empty() {
        vec![]
    } else {
        parse_sig_types(types_str)
            .map_err(|_| format!("invalid function signature `{}`", sig))?
    };

    // Find matching function
    // Only match functions with empty outputs (this is the observed behavior)
    for func in functions {
        if func.name != name {
            continue;
        }

        if !func.outputs.is_empty() {
            continue;
        }

        // Check input types match
        if func.inputs.len() != input_types.len() {
            continue;
        }

        let types_match = func.inputs.iter().zip(input_types.iter())
            .all(|(param, type_)| {
                &param.type_ == type_
            });

        if types_match {
            return Ok(func);
        }
    }

    Err(format!("invalid function signature `{}`", sig))
}

fn find_event_by_signature<'a>(events: &'a [AbiEvent], sig: &str) -> Result<&'a AbiEvent, String> {
    let paren_pos = sig.find('(')
        .ok_or_else(|| format!("invalid event signature `{}`", sig))?;

    let name = &sig[..paren_pos];
    let types_str = &sig[paren_pos+1..sig.len()-1];

    let input_types = if types_str.is_empty() {
        vec![]
    } else {
        parse_sig_types(types_str)
            .map_err(|_| format!("invalid event signature `{}`", sig))?
    };

    for event in events {
        if event.name != name {
            continue;
        }

        let non_indexed: Vec<_> = event.inputs.iter().collect();

        // Check all input types (indexed and non-indexed)
        if event.inputs.len() != input_types.len() {
            continue;
        }

        let types_match = event.inputs.iter().zip(input_types.iter())
            .all(|(param, type_)| {
                &param.type_ == type_
            });

        if types_match {
            return Ok(event);
        }
    }

    Err(format!("invalid event signature `{}`", sig))
}

fn parse_sig_types(s: &str) -> Result<Vec<Type>, String> {
    if s.is_empty() {
        return Ok(vec![]);
    }

    // Split by commas at depth 0
    let parts = split_by_comma(s);
    parts.iter().map(|p| Type::parse(p)).collect()
}

fn split_by_comma(s: &str) -> Vec<&str> {
    let mut parts = Vec::new();
    let mut depth = 0i32;
    let mut start = 0;

    for (i, b) in s.bytes().enumerate() {
        match b {
            b'(' | b'[' => depth += 1,
            b')' | b']' => depth -= 1,
            b',' if depth == 0 => {
                parts.push(&s[start..i]);
                start = i + 1;
            }
            _ => {}
        }
    }
    parts.push(&s[start..]);
    parts
}

