}

fn apply_array_suffix(t: Type, suffix: &str) -> Result<Type, String> {
    if suffix.is_empty() {
        return Ok(t);
    }

    if !suffix.starts_with('[') {
        return Err(format!("Invalid type suffix: {}", suffix));
    }

    let close = suffix.find(']')
        .ok_or_else(|| format!("Unclosed bracket in type suffix: {}", suffix))?;
    let size_str = &suffix[1..close];
    let rest = &suffix[close+1..];

    let arr_type = if size_str.is_empty() {
        crate::types::Type::Array(Box::new(t))
    } else {
        let size: usize = size_str.parse()
            .map_err(|_| format!("Invalid array size: {}", size_str))?;
        crate::types::Type::FixedArray(Box::new(t), size)
    };

    apply_array_suffix(arr_type, rest)
}

// Simple JSON value type
#[derive(Debug, Clone)]
pub enum JsonValue {
    Null,
    Bool(bool),
    Number(f64),
    String(std::string::String),
    Array(Vec<JsonValue>),
    Object(Vec<(std::string::String, JsonValue)>),
}

fn json_get_string(val: &JsonValue, key: &str) -> Option<String> {
    if let JsonValue::Object(fields) = val {
        for (k, v) in fields {
            if k == key {
                if let JsonValue::String(s) = v {
                    return Some(s.clone());
                }
            }
        }
    }
    None
}

fn json_get_bool(val: &JsonValue, key: &str) -> Option<bool> {
    if let JsonValue::Object(fields) = val {
        for (k, v) in fields {
            if k == key {
                if let JsonValue::Bool(b) = v {
                    return Some(*b);
                }
            }
        }
    }
    None
}

fn json_get_array(val: &JsonValue, key: &str) -> Option<Vec<JsonValue>> {
    if let JsonValue::Object(fields) = val {
        for (k, v) in fields {
            if k == key {
                if let JsonValue::Array(arr) = v {
                    return Some(arr.clone());
                }
            }
        }
    }
    None
}

fn json_parse_array(s: &str) -> Result<Vec<JsonValue>, String> {
    let s = s.trim();
    if s.starts_with('[') {
        if let (JsonValue::Array(arr), _) = parse_json_value(s, 0)? {
            return Ok(arr);
        }
    }
    Err(format!("Expected JSON array"))
}

fn parse_json_value(s: &str, pos: usize) -> Result<(JsonValue, usize), String> {
    let bytes = s.as_bytes();
    let mut i = pos;

    // Skip whitespace
    while i < bytes.len() && (bytes[i] == b' ' || bytes[i] == b'\t' || bytes[i] == b'\n' || bytes[i] == b'\r') {
        i += 1;
    }

    if i >= bytes.len() {
        return Err("Unexpected end of JSON".to_string());
    }

    match bytes[i] {
        b'{' => parse_json_object(s, i),
        b'[' => parse_json_array_value(s, i),
        b'"' => parse_json_string(s, i),
        b't' => {
            if s[i..].starts_with("true") {
                Ok((JsonValue::Bool(true), i + 4))
            } else {
                Err(format!("Invalid JSON at position {}", i))
            }
        }
        b'f' => {
            if s[i..].starts_with("false") {
                Ok((JsonValue::Bool(false), i + 5))
            } else {
                Err(format!("Invalid JSON at position {}", i))
            }
        }
        b'n' => {
            if s[i..].starts_with("null") {
                Ok((JsonValue::Null, i + 4))
            } else {
                Err(format!("Invalid JSON at position {}", i))
            }
        }
        b'0'..=b'9' | b'-' => parse_json_number(s, i),
        _ => Err(format!("Unexpected character '{}' at position {}", bytes[i] as char, i)),
    }
}

fn skip_whitespace(bytes: &[u8], mut i: usize) -> usize {
    while i < bytes.len() && (bytes[i] == b' ' || bytes[i] == b'\t' || bytes[i] == b'\n' || bytes[i] == b'\r') {
        i += 1;
    }
    i
}

fn parse_json_object(s: &str, pos: usize) -> Result<(JsonValue, usize), String> {
    let bytes = s.as_bytes();
    let mut i = pos + 1; // skip '{'
    let mut fields = Vec::new();

    i = skip_whitespace(bytes, i);

    if i < bytes.len() && bytes[i] == b'}' {
        return Ok((JsonValue::Object(fields), i + 1));
    }

    loop {
        i = skip_whitespace(bytes, i);

        // Parse key
        let (key_val, new_i) = parse_json_string(s, i)?;
        let key = if let JsonValue::String(k) = key_val { k } else { return Err("Expected string key".to_string()); };
        i = new_i;

        i = skip_whitespace(bytes, i);

        if i >= bytes.len() || bytes[i] != b':' {
            return Err(format!("Expected ':' at position {}", i));
        }
        i += 1;

        i = skip_whitespace(bytes, i);

        // Parse value
        let (val, new_i) = parse_json_value(s, i)?;
        fields.push((key, val));
        i = new_i;

        i = skip_whitespace(bytes, i);

        if i >= bytes.len() {
            return Err("Unexpected end of JSON object".to_string());
        }

        match bytes[i] {
            b',' => { i += 1; }
            b'}' => { i += 1; break; }
            _ => return Err(format!("Expected ',' or '}}' at position {}", i)),
        }
    }

    Ok((JsonValue::Object(fields), i))
}

fn parse_json_array_value(s: &str, pos: usize) -> Result<(JsonValue, usize), String> {
    let bytes = s.as_bytes();
    let mut i = pos + 1; // skip '['
    let mut items = Vec::new();

    i = skip_whitespace(bytes, i);

    if i < bytes.len() && bytes[i] == b']' {
        return Ok((JsonValue::Array(items), i + 1));
    }

    loop {
        i = skip_whitespace(bytes, i);

        let (val, new_i) = parse_json_value(s, i)?;
        items.push(val);
        i = new_i;

        i = skip_whitespace(bytes, i);

        if i >= bytes.len() {
            return Err("Unexpected end of JSON array".to_string());
        }

        match bytes[i] {
            b',' => { i += 1; }
            b']' => { i += 1; break; }
            _ => return Err(format!("Expected ',' or ']' at position {}", i)),
        }
    }

    Ok((JsonValue::Array(items), i))
}

fn parse_json_string(s: &str, pos: usize) -> Result<(JsonValue, usize), String> {
    let bytes = s.as_bytes();
    if bytes[pos] != b'"' {
        return Err(format!("Expected '\"' at position {}", pos));
    }

    let mut result = String::new();
    let mut i = pos + 1;

    while i < bytes.len() {
        match bytes[i] {
            b'"' => {
                i += 1;
                return Ok((JsonValue::String(result), i));
            }
            b'\\' => {
                i += 1;
                if i >= bytes.len() {
                    return Err("Unexpected end of string escape".to_string());
                }
                match bytes[i] {
                    b'"' => result.push('"'),
                    b'\\' => result.push('\\'),
                    b'/' => result.push('/'),
                    b'n' => result.push('\n'),
                    b'r' => result.push('\r'),
                    b't' => result.push('\t'),
                    b'b' => result.push('\x08'),
                    b'f' => result.push('\x0C'),
                    b'u' => {
                        // Unicode escape \uXXXX
                        if i + 4 >= bytes.len() {
                            return Err("Invalid unicode escape".to_string());
                        }
                        let hex_str = &s[i+1..i+5];
                        let code_point = u32::from_str_radix(hex_str, 16)
                            .map_err(|_| format!("Invalid unicode escape at position {}", i))?;
                        if let Some(ch) = char::from_u32(code_point) {
                            result.push(ch);
                        }
                        i += 4;
                    }
                    c => {
                        result.push('\\');
                        result.push(c as char);
                    }
                }
                i += 1;
            }
            b => {
                result.push(b as char);
                i += 1;
            }
        }
    }

    Err("Unterminated string".to_string())
}

fn parse_json_number(s: &str, pos: usize) -> Result<(JsonValue, usize), String> {
    let bytes = s.as_bytes();
    let mut i = pos;

    if i < bytes.len() && bytes[i] == b'-' {
        i += 1;
    }

    while i < bytes.len() && bytes[i].is_ascii_digit() {
        i += 1;
    }

    if i < bytes.len() && bytes[i] == b'.' {
        i += 1;
        while i < bytes.len() && bytes[i].is_ascii_digit() {
            i += 1;
        }
    }

    if i < bytes.len() && (bytes[i] == b'e' || bytes[i] == b'E') {
        i += 1;
        if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
            i += 1;
        }
        while i < bytes.len() && bytes[i].is_ascii_digit() {
            i += 1;
        }
    }

    let num_str = &s[pos..i];
    let num: f64 = num_str.parse().map_err(|_| format!("Invalid number: {}", num_str))?;

    Ok((JsonValue::Number(num), i))
}
