            apply_array_suffix(Type::Tuple(comp_types), suffix)?
        } else {
            Type::parse(&type_str)?
        };

        inputs.push(AbiEventParam { name: param_name, type_, indexed, components });
    }

    Ok(AbiEvent { name, anonymous, inputs })
