        // Parse key
        let (key_val, new_i) = parse_json_string(s, i)?;
        let key = if let JsonValue::String(k) = key_val { k } else { return Err("Expected string key".to_string()); };
        i = new_i;

        i = skip_whitespace(bytes, i);

        if i >= bytes.len() || bytes[i] != b':' {
            return Err(format!("Expected ':' at position {}", i));
        }
        i += 1;

        i = skip_whitespace(bytes, i);

        // Parse value
        let (val, new_i) = parse_json_value(s, i)?;
        fields.push((key, val));
        i = new_i;

        i = skip_whitespace(bytes, i);

        if i >= bytes.len() {
            return Err("Unexpected end of JSON object".to_string());
        }

        match bytes[i] {
            b',' => { i += 1; }
            b'}' => { i += 1; break; }
            _ => return Err(format!("Expected ',' or '}}' at position {}", i)),
        }
    }

    Ok((JsonValue::Object(fields), i))
}

fn parse_json_array_value(s: &str, pos: usize) -> Result<(JsonValue, usize), String> {
    let bytes = s.as_bytes();
    let mut i = pos + 1; // skip '['
    let mut items = Vec::new();

    i = skip_whitespace(bytes, i);

    if i < bytes.len() && bytes[i] == b']' {
        return Ok((JsonValue::Array(items), i + 1));
    }

    loop {
        i = skip_whitespace(bytes, i);

        let (val, new_i) = parse_json_value(s, i)?;
        items.push(val);
        i = new_i;

        i = skip_whitespace(bytes, i);

        if i >= bytes.len() {
            return Err("Unexpected end of JSON array".to_string());
        }

        match bytes[i] {
            b',' => { i += 1; }
            b']' => { i += 1; break; }
            _ => return Err(format!("Expected ',' or ']' at position {}", i)),
        }
    }

    Ok((JsonValue::Array(items), i))
}

fn parse_json_string(s: &str, pos: usize) -> Result<(JsonValue, usize), String> {
    let bytes = s.as_bytes();
    if bytes[pos] != b'"' {
        return Err(format!("Expected '\"' at position {}", pos));
    }

    let mut result = String::new();
    let mut i = pos + 1;

    while i < bytes.len() {
        match bytes[i] {
            b'"' => {
                i += 1;
                return Ok((JsonValue::String(result), i));
            }
            b'\\' => {
                i += 1;
                if i >= bytes.len() {
                    return Err("Unexpected end of string escape".to_string());
                }
                match bytes[i] {
                    b'"' => result.push('"'),
                    b'\\' => result.push('\\'),
                    b'/' => result.push('/'),
                    b'n' => result.push('\n'),
                    b'r' => result.push('\r'),
                    b't' => result.push('\t'),
                    b'b' => result.push('\x08'),
                    b'f' => result.push('\x0C'),
                    b'u' => {
                        // Unicode escape \uXXXX
                        if i + 4 >= bytes.len() {
                            return Err("Invalid unicode escape".to_string());
                        }
                        let hex_str = &s[i+1..i+5];
                        let code_point = u32::from_str_radix(hex_str, 16)
                            .map_err(|_| format!("Invalid unicode escape at position {}", i))?;
                        if let Some(ch) = char::from_u32(code_point) {
                            result.push(ch);
                        }
                        i += 4;
                    }
                    c => {
                        result.push('\\');
                        result.push(c as char);
                    }
                }
                i += 1;
            }
            b => {
                result.push(b as char);
                i += 1;
            }
        }
    }

    Err("Unterminated string".to_string())
}

fn parse_json_number(s: &str, pos: usize) -> Result<(JsonValue, usize), String> {
    let bytes = s.as_bytes();
    let mut i = pos;

    if i < bytes.len() && bytes[i] == b'-' {
        i += 1;
    }

    while i < bytes.len() && bytes[i].is_ascii_digit() {
        i += 1;
    }

    if i < bytes.len() && bytes[i] == b'.' {
        i += 1;
        while i < bytes.len() && bytes[i].is_ascii_digit() {
            i += 1;
        }
    }

    if i < bytes.len() && (bytes[i] == b'e' || bytes[i] == b'E') {
        i += 1;
        if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
            i += 1;
        }
        while i < bytes.len() && bytes[i].is_ascii_digit() {
            i += 1;
        }
    }

    let num_str = &s[pos..i];
    let num: f64 = num_str.parse().map_err(|_| format!("Invalid number: {}", num_str))?;

    Ok((JsonValue::Number(num), i))
}
