/// Parse command line args for `encode function`
fn run_encode_function(args: &[String]) -> Result<(), String> {
    let mut lenient = false;
    let mut abi_path = None;
    let mut func_name = None;
    let mut params: Vec<String> = Vec::new();

    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "--help" | "-h" => {
                print_encode_function_help();
                return Ok(());
            }
            "--version" | "-V" => {
                let app = std::env::args().next().unwrap_or_default();
                let name = std::path::Path::new(&app)
                    .file_name()
                    .and_then(|n| n.to_str())
                    .unwrap_or("ethabi")
                    .to_string();
                println!("{}-encode-function 18.0.0", name);
                return Ok(());
            }
            "--lenient" | "-l" => {
                lenient = true;
            }
            "-p" => {
                if i + 1 >= args.len() {
                    eprintln!("error: -p requires a value");
                    std::process::exit(1);
                }
                i += 1;
                params.push(args[i].clone());
            }
            arg if arg.starts_with("-p") => {
                params.push(args[i][2..].to_string());
            }
            _ => {
                if abi_path.is_none() {
                    abi_path = Some(args[i].clone());
                } else if func_name.is_none() {
                    func_name = Some(args[i].clone());
                } else {
                    // Extra params?
                }
            }
        }
        i += 1;
    }

    let abi_path = abi_path.ok_or_else(|| {
        eprintln!("error: Missing required argument <abi-path>");
        std::process::exit(1);
    })?;
    let func_name = func_name.ok_or_else(|| {
        eprintln!("error: Missing required argument <function-name-or-signature>");
        std::process::exit(1);
    })?;

    // Load and parse ABI
    let abi_json = fs::read_to_string(&abi_path)
        .map_err(|e| e.to_string())?;
    let contract = Contract::from_json(&abi_json)
        .map_err(|e| e.to_string())?;

    let func = contract.find_function(&func_name)?;

    // Parse params
    if params.len() != func.inputs.len() && !params.is_empty() {
        return Err("Invalid data".to_string());
    }

    let tokens: Result<Vec<Token>, String> = if params.is_empty() && func.inputs.is_empty() {
        Ok(vec![])
    } else if params.len() == func.inputs.len() {
        func.inputs.iter().zip(params.iter())
            .map(|(input, param)| {
                if lenient {
                    parse_param_lenient(&input.type_, param)
                } else {
                    parse_param(&input.type_, param)
                }
            })
            .collect()
    } else {
        return Err("Invalid data".to_string());
    };

    let tokens = tokens?;

    // Encode: selector + params
    let selector = function_selector(func);
    let encoded = encode(&tokens);

    let mut result = hex_encode(&selector);
    result.push_str(&hex_encode(&encoded));

    println!("{}", result);
    Ok(())
}

/// Parse command line args for `encode params`
fn run_encode_params(args: &[String]) -> Result<(), String> {
    let mut lenient = false;
    let mut type_param_pairs: Vec<(String, String)> = Vec::new();

    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "--help" | "-h" => {
                print_encode_params_help();
                return Ok(());
            }
            "--version" | "-V" => {
                let app = std::env::args().next().unwrap_or_default();
                let name = std::path::Path::new(&app)
                    .file_name()
                    .and_then(|n| n.to_str())
                    .unwrap_or("ethabi")
                    .to_string();
                println!("{}-encode-params 18.0.0", name);
                return Ok(());
            }
            "--lenient" | "-l" => {
                lenient = true;
            }
            "-v" => {
                if i + 2 >= args.len() {
                    eprintln!("error: The argument '-v <type-or-param> <type-or-param>' requires 2 values, but {} was provided", if i + 1 >= args.len() { 0 } else { 1 });
                    eprintln!();
                    eprintln!("USAGE:");
                    let app = std::env::args().next().unwrap_or_default();
                    let name = std::path::Path::new(&app)
                        .file_name()
                        .and_then(|n| n.to_str())
                        .unwrap_or("ethabi")
                        .to_string();
                    eprintln!("    {} encode params -v <type-or-param> <type-or-param>", name);
                    eprintln!();
                    eprintln!("For more information try --help");
                    std::process::exit(1);
                }
                type_param_pairs.push((args[i+1].clone(), args[i+2].clone()));
                i += 2;
            }
            _ => {
                // Unknown arg, could be error
            }
        }
        i += 1;
    }

    // Parse and encode
    let mut tokens = Vec::new();
    for (type_str, param_str) in &type_param_pairs {
        let type_ = Type::parse(type_str)
            .map_err(|_| "Invalid data".to_string())?;
        let token = if lenient {
            parse_param_lenient(&type_, param_str)
        } else {
            parse_param(&type_, param_str)
        }.map_err(|e| {
            // Wrap the error with hex parsing context if it's a hex error
            if e.contains("Odd number of digits") || e.contains("Invalid character") {
                format!("Hex parsing error: {}\n\nCaused by:\n    {}", e, e)
            } else {
                e
            }
        })?;
        tokens.push(token);
    }

    let encoded = encode(&tokens);
    println!("{}", hex_encode(&encoded));
    Ok(())
}

/// Parse command line args for `decode function`
fn run_decode_function(args: &[String]) -> Result<(), String> {
    let mut abi_path = None;
    let mut func_name = None;
    let mut data = None;

    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "--help" | "-h" => {
                print_decode_function_help();
                return Ok(());
            }
            "--version" | "-V" => {
                let app = std::env::args().next().unwrap_or_default();
                let name = std::path::Path::new(&app)
                    .file_name()
                    .and_then(|n| n.to_str())
                    .unwrap_or("ethabi")
                    .to_string();
                println!("{}-decode-function 18.0.0", name);
                return Ok(());
            }
            _ => {
                if abi_path.is_none() {
                    abi_path = Some(args[i].clone());
                } else if func_name.is_none() {
                    func_name = Some(args[i].clone());
                } else if data.is_none() {
                    data = Some(args[i].clone());
                }
            }
        }
        i += 1;
    }

    let abi_path = abi_path.ok_or("Missing abi-path")?;
    let func_name = func_name.ok_or("Missing function-name-or-signature")?;
    let data_str = data.ok_or("Missing data")?;

    let abi_json = fs::read_to_string(&abi_path).map_err(|e| e.to_string())?;
    let contract = Contract::from_json(&abi_json).map_err(|e| e.to_string())?;
    let func = contract.find_function(&func_name)?;

    let data_bytes = decode_hex(&data_str).map_err(|e| e.to_string())?;

    if data_bytes.is_empty() && func.outputs.is_empty() {
        // Nothing to decode
        return Ok(());
    }

    let output_types: Vec<Type> = func.outputs.iter().map(|o| o.type_.clone()).collect();

    if output_types.is_empty() {
        return Ok(());
    }

    let tokens = decode(&output_types, &data_bytes).map_err(|e| e.to_string())?;

    for (i, token) in tokens.iter().enumerate() {
        let type_name = output_types[i].display_name();
        println!("{} {}", type_name, format_token(token));
    }

