/// Parse command line args for `encode function`
fn run_encode_function(args: &[String]) -> Result<(), String> {
    let mut lenient = false;
    let mut abi_path = None;
    let mut func_name = None;
    let mut params: Vec<String> = Vec::new();

    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "--help" | "-h" => {
                print_encode_function_help();
                return Ok(());
            }
            "--version" | "-V" => {
                let app = std::env::args().next().unwrap_or_default();
                let name = std::path::Path::new(&app)
                    .file_name()
                    .and_then(|n| n.to_str())
                    .unwrap_or("ethabi")
                    .to_string();
                println!("{}-encode-function 18.0.0", name);
                return Ok(());
            }
            "--lenient" | "-l" => {
                lenient = true;
            }
            "-p" => {
                if i + 1 >= args.len() {
                    eprintln!("error: -p requires a value");
                    std::process::exit(1);
                }
                i += 1;
                params.push(args[i].clone());
            }
            arg if arg.starts_with("-p") => {
                params.push(args[i][2..].to_string());
            }
            _ => {
                if abi_path.is_none() {
                    abi_path = Some(args[i].clone());
                } else if func_name.is_none() {
                    func_name = Some(args[i].clone());
                } else {
                    // Extra params?
                }
            }
        }
        i += 1;
    }

    let abi_path = abi_path.ok_or_else(|| {
        eprintln!("error: Missing required argument <abi-path>");
        std::process::exit(1);
    })?;
    let func_name = func_name.ok_or_else(|| {
        eprintln!("error: Missing required argument <function-name-or-signature>");
        std::process::exit(1);
    })?;

    // Load and parse ABI
    let abi_json = fs::read_to_string(&abi_path)
        .map_err(|e| e.to_string())?;
    let contract = Contract::from_json(&abi_json)
        .map_err(|e| e.to_string())?;

    let func = contract.find_function(&func_name)?;

    // Parse params
    if params.len() != func.inputs.len() && !params.is_empty() {
        return Err("Invalid data".to_string());
    }

    let tokens: Result<Vec<Token>, String> = if params.is_empty() && func.inputs.is_empty() {
        Ok(vec![])
    } else if params.len() == func.inputs.len() {
        func.inputs.iter().zip(params.iter())
            .map(|(input, param)| {
                if lenient {
                    parse_param_lenient(&input.type_, param)
                } else {
                    parse_param(&input.type_, param)
                }
            })
            .collect()
    } else {
        return Err("Invalid data".to_string());
    };

    let tokens = tokens?;

    // Encode: selector + params
    let selector = function_selector(func);
    let encoded = encode(&tokens);

    let mut result = hex_encode(&selector);
    result.push_str(&hex_encode(&encoded));

    println!("{}", result);
    Ok(())
}

