    let contract = Contract::from_json(&abi_json).map_err(|e| e.to_string())?;
    let event = contract.find_event(&event_name)?;

    // Parse topics
    let topic_bytes: Vec<Vec<u8>> = topics.iter()
        .map(|t| decode_hex(t).map_err(|e| e.to_string()))
        .collect::<Result<Vec<_>, _>>()?;

    // Parse data
    let data_bytes = decode_hex(&data_str).map_err(|e| e.to_string())?;

    // Decode the log
    decode_event_log(event, &topic_bytes, &data_bytes)
