fn run_encode_function(args: &[String], prog_name: &str) -> Result<(), String> {
    let mut lenient = false;
    let mut abi_path: Option<String> = None;
    let mut func_name: Option<String> = None;
    let mut params: Vec<String> = Vec::new();

    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "--help" | "-h" => {
                print_encode_function_help(prog_name);
                return Ok(());
            }
            "--version" | "-V" => {
                println!("{}-encode-function 18.0.0", prog_name);
                return Ok(());
            }
            "--lenient" | "-l" => {
                lenient = true;
            }
            "-p" => {
                i += 1;
                if i >= args.len() {
                    eprintln!("error: -p requires a value");
                    std::process::exit(1);
                }
                params.push(args[i].clone());
            }
            arg if arg.starts_with("-p") && arg.len() > 2 => {
                params.push(args[i][2..].to_string());
            }
            _ => {
                if abi_path.is_none() {
                    abi_path = Some(args[i].clone());
                } else if func_name.is_none() {
                    func_name = Some(args[i].clone());
                }
            }
        }
        i += 1;
    }

    let abi_path = abi_path.unwrap_or_else(|| {
        eprintln!("error: Missing required argument <abi-path>");
        std::process::exit(1);
    });
    let func_name = func_name.unwrap_or_else(|| {
        eprintln!("error: Missing required argument <function-name-or-signature>");
        std::process::exit(1);
    });

    let abi_json = fs::read_to_string(&abi_path)
        .map_err(|e| e.to_string())?;
    let contract = Contract::from_json(&abi_json)
        .map_err(|e| e.to_string())?;

    let func = contract.find_function(&func_name)?;

    let tokens: Vec<Token> = if params.is_empty() && func.inputs.is_empty() {
        vec![]
    } else if params.len() == func.inputs.len() {
        func.inputs.iter().zip(params.iter())
            .map(|(input, param)| {
                if lenient {
                    parse_param_lenient(&input.type_, param)
                } else {
                    parse_param(&input.type_, param)
                }
            })
            .collect::<Result<Vec<_>, _>>()?
    } else {
        return Err("Invalid data".to_string());
    };

    let selector = function_selector(func);
    let encoded = encode(&tokens);

    let mut result = hex_encode(&selector);
    result.push_str(&hex_encode(&encoded));

    println!("{}", result);
    Ok(())
}

fn run_encode_params(args: &[String], prog_name: &str) -> Result<(), String> {
    let mut lenient = false;
    let mut type_param_pairs: Vec<(String, String)> = Vec::new();

    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "--help" | "-h" => {
                print_encode_params_help(prog_name);
                return Ok(());
            }
            "--version" | "-V" => {
                println!("{}-encode-params 18.0.0", prog_name);
                return Ok(());
            }
            "--lenient" | "-l" => {
                lenient = true;
            }
            "-v" => {
                // Need exactly 2 more arguments
                if i + 1 >= args.len() {
                    eprintln!("error: The argument '-v <type-or-param> <type-or-param>' requires 2 values, but 0 was provided");
                    eprintln!();
                    eprintln!("USAGE:");
                    eprintln!("    {} encode params -v <type-or-param> <type-or-param>", prog_name);
                    eprintln!();
                    eprintln!("For more information try --help");
                    std::process::exit(1);
                }
                if i + 2 >= args.len() {
                    eprintln!("error: The argument '-v <type-or-param> <type-or-param>' requires 2 values, but 1 was provided");
                    eprintln!();
                    eprintln!("USAGE:");
                    eprintln!("    {} encode params -v <type-or-param> <type-or-param>", prog_name);
                    eprintln!();
                    eprintln!("For more information try --help");
                    std::process::exit(1);
                }
                type_param_pairs.push((args[i+1].clone(), args[i+2].clone()));
                i += 2;
            }
            _ => {}
        }
        i += 1;
    }

    let mut tokens = Vec::new();
    for (type_str, param_str) in &type_param_pairs {
        let type_ = Type::parse(type_str)
            .map_err(|_| "Invalid data".to_string())?;
        let token = if lenient {
            parse_param_lenient(&type_, param_str)
        } else {
            parse_param(&type_, param_str)
        }.map_err(|e| {
            if e.contains("Odd number of digits") || e.contains("Invalid character") {
                format!("Hex parsing error: {}\n\nCaused by:\n    {}", e, e)
            } else {
                e
            }
        })?;
        tokens.push(token);
    }

    let encoded = encode(&tokens);
    println!("{}", hex_encode(&encoded));
    Ok(())
}

