                return Ok(());
            }
            _ => {
                if abi_path.is_none() {
                    abi_path = Some(args[i].clone());
                } else if func_name.is_none() {
                    func_name = Some(args[i].clone());
                } else if data.is_none() {
                    data = Some(args[i].clone());
                }
            }
        }
        i += 1;
    }

    let abi_path = abi_path.ok_or("Missing abi-path")?;
    let func_name = func_name.ok_or("Missing function-name-or-signature")?;
    let data_str = data.ok_or("Missing data")?;

    let abi_json = fs::read_to_string(&abi_path).map_err(|e| e.to_string())?;
    let contract = Contract::from_json(&abi_json).map_err(|e| e.to_string())?;
    let func = contract.find_function(&func_name)?;

    let data_bytes = decode_hex(&data_str).map_err(|e| e.to_string())?;

    let output_types: Vec<Type> = func.outputs.iter().map(|o| o.type_.clone()).collect();

    if output_types.is_empty() {
        return Ok(());
    }

    if data_bytes.is_empty() {
        return Err(DecodeError::EmptyData.to_string());
    }

    let tokens = decode(&output_types, &data_bytes).map_err(|e| e.to_string())?;

    for (i, token) in tokens.iter().enumerate() {
        let type_name = output_types[i].display_name();
        println!("{} {}", type_name, format_token(token));
    }

    Ok(())
}

