fn run_decode_log(args: &[String], prog_name: &str) -> Result<(), String> {
    let mut abi_path: Option<String> = None;
    let mut event_name: Option<String> = None;
    let mut topics: Vec<String> = Vec::new();
    let mut data: Option<String> = None;

    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "--help" | "-h" => {
                print_decode_log_help(prog_name);
                return Ok(());
            }
            "--version" | "-V" => {
                println!("{}-decode-log 18.0.0", prog_name);
                return Ok(());
            }
            "-l" => {
                i += 1;
                if i >= args.len() {
                    eprintln!("error: -l requires a value");
                    std::process::exit(1);
                }
                topics.push(args[i].clone());
            }
            _ => {
                if abi_path.is_none() {
                    abi_path = Some(args[i].clone());
                } else if event_name.is_none() {
                    event_name = Some(args[i].clone());
                } else if data.is_none() {
                    data = Some(args[i].clone());
                }
            }
        }
        i += 1;
    }

    let abi_path = abi_path.ok_or("Missing abi-path")?;
    let event_name = event_name.ok_or("Missing event-name-or-signature")?;
    let data_str = data.ok_or("Missing data")?;

    let abi_json = fs::read_to_string(&abi_path).map_err(|e| e.to_string())?;
    let contract = Contract::from_json(&abi_json).map_err(|e| e.to_string())?;
    let event = contract.find_event(&event_name)?;

    let topic_bytes: Vec<Vec<u8>> = topics.iter()
        .map(|t| decode_hex(t).map_err(|e| e.to_string()))
        .collect::<Result<Vec<_>, _>>()?;

    let data_bytes = decode_hex(&data_str).map_err(|e| e.to_string())?;

    decode_event_log(event, &topic_bytes, &data_bytes)
}

fn decode_event_log(event: &AbiEvent, topics: &[Vec<u8>], data: &[u8]) -> Result<(), String> {
    let mut topic_iter = topics.iter();

    if !event.anonymous {
        let sig = event_selector(event);
        let first_topic = topic_iter.next()
            .ok_or_else(|| "Invalid data".to_string())?;
        if first_topic.len() != 32 || first_topic.as_slice() != sig.as_ref() {
            return Err("Invalid data".to_string());
        }
    }

    let non_indexed_params: Vec<_> = event.inputs.iter().filter(|p| !p.indexed).collect();

    let non_indexed_types: Vec<Type> = non_indexed_params.iter()
        .map(|p| p.type_.clone())
        .collect();

    let data_tokens = if non_indexed_types.is_empty() {
        vec![]
    } else if data.is_empty() {
        return Err(DecodeError::EmptyData.to_string());
    } else {
        decode(&non_indexed_types, data).map_err(|e| e.to_string())?
    };

    let mut data_idx = 0;

    for param in &event.inputs {
        if param.indexed {
            let topic_data = topic_iter.next()
                .ok_or_else(|| "Invalid data".to_string())?;
            let val = decode_indexed_param(&param.type_, topic_data)?;
            println!("{} {}", param.name, val);
        } else {
            println!("{} {}", param.name, format_token(&data_tokens[data_idx]));
            data_idx += 1;
        }
    }

    Ok(())
}

fn decode_indexed_param(type_: &Type, data: &[u8]) -> Result<String, String> {
    match type_ {
        Type::Bool | Type::Uint(_) | Type::Int(_) | Type::Address | Type::FixedBytes(_) => {
            if data.len() != 32 {
                return Err("Invalid data".to_string());
            }
            let tokens = decode(&[type_.clone()], data).map_err(|e| e.to_string())?;
            Ok(format_token(&tokens[0]))
        }
        _ => {
            Ok(hex_encode(data))
        }
    }
}
