    } else if params.len() == func.inputs.len() {
        func.inputs.iter().zip(params.iter())
            .map(|(input, param)| {
                if lenient {
                    parse_param_lenient(&input.type_, param)
                } else {
                    parse_param(&input.type_, param)
                }
            })
            .collect::<Result<Vec<_>, _>>()?
    } else {
        return Err("Invalid data".to_string());
    };

    let selector = function_selector(func);
    let encoded = encode(&tokens);

    let mut result = hex_encode(&selector);
    result.push_str(&hex_encode(&encoded));

    println!("{}", result);
    Ok(())
}

fn run_encode_params(args: &[String], prog_name: &str) -> Result<(), String> {
    let mut lenient = false;
    let mut type_param_pairs: Vec<(String, String)> = Vec::new();

    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "--help" | "-h" => {
                print_encode_params_help(prog_name);
                return Ok(());
            }
            "--version" | "-V" => {
                println!("{}-encode-params 18.0.0", prog_name);
                return Ok(());
            }
            "--lenient" | "-l" => {
                lenient = true;
            }
            "-v" => {
                // Need exactly 2 more arguments
                if i + 1 >= args.len() {
                    eprintln!("error: The argument '-v <type-or-param> <type-or-param>' requires 2 values, but 0 was provided");
                    eprintln!();
                    eprintln!("USAGE:");
                    eprintln!("    {} encode params -v <type-or-param> <type-or-param>", prog_name);
                    eprintln!();
                    eprintln!("For more information try --help");
                    std::process::exit(1);
                }
                if i + 2 >= args.len() {
                    eprintln!("error: The argument '-v <type-or-param> <type-or-param>' requires 2 values, but 1 was provided");
                    eprintln!();
                    eprintln!("USAGE:");
                    eprintln!("    {} encode params -v <type-or-param> <type-or-param>", prog_name);
                    eprintln!();
                    eprintln!("For more information try --help");
                    std::process::exit(1);
                }
                type_param_pairs.push((args[i+1].clone(), args[i+2].clone()));
                i += 2;
            }
            _ => {}
        }
        i += 1;
    }

    let mut tokens = Vec::new();
    for (type_str, param_str) in &type_param_pairs {
        let type_ = Type::parse(type_str)
            .map_err(|_| "Invalid data".to_string())?;
        let token = if lenient {
            parse_param_lenient(&type_, param_str)
        } else {
            parse_param(&type_, param_str)
        }.map_err(|e| {
            if e.contains("Odd number of digits") || e.contains("Invalid character") {
                format!("Hex parsing error: {}\n\nCaused by:\n    {}", e, e)
            } else {
                e
            }
        })?;
        tokens.push(token);
    }

    let encoded = encode(&tokens);
    println!("{}", hex_encode(&encoded));
    Ok(())
}

fn run_decode_function(args: &[String], prog_name: &str) -> Result<(), String> {
    let mut abi_path: Option<String> = None;
    let mut func_name: Option<String> = None;
    let mut data: Option<String> = None;

    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "--help" | "-h" => {
                print_decode_function_help(prog_name);
                return Ok(());
            }
            "--version" | "-V" => {
                println!("{}-decode-function 18.0.0", prog_name);
                return Ok(());
            }
            _ => {
                if abi_path.is_none() {
                    abi_path = Some(args[i].clone());
                } else if func_name.is_none() {
                    func_name = Some(args[i].clone());
                } else if data.is_none() {
                    data = Some(args[i].clone());
                }
            }
        }
        i += 1;
    }

    let abi_path = abi_path.ok_or("Missing abi-path")?;
    let func_name = func_name.ok_or("Missing function-name-or-signature")?;
    let data_str = data.ok_or("Missing data")?;

    let abi_json = fs::read_to_string(&abi_path).map_err(|e| e.to_string())?;
    let contract = Contract::from_json(&abi_json).map_err(|e| e.to_string())?;
    let func = contract.find_function(&func_name)?;

    let data_bytes = decode_hex(&data_str).map_err(|e| e.to_string())?;

    let output_types: Vec<Type> = func.outputs.iter().map(|o| o.type_.clone()).collect();

    if output_types.is_empty() {
        return Ok(());
    }

    if data_bytes.is_empty() {
        return Err(DecodeError::EmptyData.to_string());
    }

    let tokens = decode(&output_types, &data_bytes).map_err(|e| e.to_string())?;

    for (i, token) in tokens.iter().enumerate() {
        let type_name = output_types[i].display_name();
        println!("{} {}", type_name, format_token(token));
    }

    Ok(())
}

fn run_decode_params(args: &[String], prog_name: &str) -> Result<(), String> {
    let mut types: Vec<String> = Vec::new();
    let mut data: Option<String> = None;

    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "--help" | "-h" => {
                print_decode_params_help(prog_name);
                return Ok(());
            }
            "--version" | "-V" => {
                println!("{}-decode-params 18.0.0", prog_name);
                return Ok(());
            }
            "-t" => {
                i += 1;
                if i >= args.len() {
                    eprintln!("error: -t requires a value");
                    std::process::exit(1);
                }
                types.push(args[i].clone());
            }
            _ => {
                if data.is_none() {
                    data = Some(args[i].clone());
                }
            }
        }
        i += 1;
    }

    let data_str = data.ok_or("Missing data")?;

    let data_bytes = decode_hex(&data_str).map_err(|e| e.to_string())?;

    let parsed_types: Vec<Type> = types.iter()
        .map(|t| Type::parse(t))
        .collect::<Result<Vec<_>, _>>()?;

    if parsed_types.is_empty() {
        return Ok(());
    }

    let tokens = decode(&parsed_types, &data_bytes).map_err(|e| e.to_string())?;

    for (i, token) in tokens.iter().enumerate() {
        let type_name = parsed_types[i].display_name();
        println!("{} {}", type_name, format_token(token));
    }

    Ok(())
}

fn run_decode_log(args: &[String], prog_name: &str) -> Result<(), String> {
    let mut abi_path: Option<String> = None;
    let mut event_name: Option<String> = None;
    let mut topics: Vec<String> = Vec::new();
    let mut data: Option<String> = None;

    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "--help" | "-h" => {
                print_decode_log_help(prog_name);
                return Ok(());
            }
            "--version" | "-V" => {
                println!("{}-decode-log 18.0.0", prog_name);
                return Ok(());
            }
            "-l" => {
                i += 1;
                if i >= args.len() {
                    eprintln!("error: -l requires a value");
                    std::process::exit(1);
                }
                topics.push(args[i].clone());
            }
            _ => {
                if abi_path.is_none() {
                    abi_path = Some(args[i].clone());
                } else if event_name.is_none() {
                    event_name = Some(args[i].clone());
                } else if data.is_none() {
                    data = Some(args[i].clone());
                }
            }
        }
        i += 1;
    }

    let abi_path = abi_path.ok_or("Missing abi-path")?;
    let event_name = event_name.ok_or("Missing event-name-or-signature")?;
    let data_str = data.ok_or("Missing data")?;

    let abi_json = fs::read_to_string(&abi_path).map_err(|e| e.to_string())?;
    let contract = Contract::from_json(&abi_json).map_err(|e| e.to_string())?;
    let event = contract.find_event(&event_name)?;

    let topic_bytes: Vec<Vec<u8>> = topics.iter()
        .map(|t| decode_hex(t).map_err(|e| e.to_string()))
        .collect::<Result<Vec<_>, _>>()?;

    let data_bytes = decode_hex(&data_str).map_err(|e| e.to_string())?;

    decode_event_log(event, &topic_bytes, &data_bytes)
}

fn decode_event_log(event: &AbiEvent, topics: &[Vec<u8>], data: &[u8]) -> Result<(), String> {
    let mut topic_iter = topics.iter();

    if !event.anonymous {
        let sig = event_selector(event);
        let first_topic = topic_iter.next()
            .ok_or_else(|| "Invalid data".to_string())?;
        if first_topic.len() != 32 || first_topic.as_slice() != sig.as_ref() {
            return Err("Invalid data".to_string());
        }
    }

    let non_indexed_params: Vec<_> = event.inputs.iter().filter(|p| !p.indexed).collect();

    let non_indexed_types: Vec<Type> = non_indexed_params.iter()
        .map(|p| p.type_.clone())
        .collect();

    let data_tokens = if non_indexed_types.is_empty() {
        vec![]
    } else if data.is_empty() {
        return Err(DecodeError::EmptyData.to_string());
    } else {
        decode(&non_indexed_types, data).map_err(|e| e.to_string())?
    };

    let mut data_idx = 0;

    for param in &event.inputs {
        if param.indexed {
            let topic_data = topic_iter.next()
                .ok_or_else(|| "Invalid data".to_string())?;
            let val = decode_indexed_param(&param.type_, topic_data)?;
            println!("{} {}", param.name, val);
        } else {
            println!("{} {}", param.name, format_token(&data_tokens[data_idx]));
            data_idx += 1;
        }
    }

    Ok(())
}

fn decode_indexed_param(type_: &Type, data: &[u8]) -> Result<String, String> {
    match type_ {
        Type::Bool | Type::Uint(_) | Type::Int(_) | Type::Address | Type::FixedBytes(_) => {
            if data.len() != 32 {
                return Err("Invalid data".to_string());
            }
            let tokens = decode(&[type_.clone()], data).map_err(|e| e.to_string())?;
            Ok(format_token(&tokens[0]))
        }
        _ => {
            Ok(hex_encode(data))
        }
    }
}
